function ck($x,$n){if(!$x)throw new RuntimeException($n);echo "PASS $n\n";}
function group(string $name,callable $fn):void{global $fail;try{$fn();echo "GROUP PASS $name\n";}catch(Throwable $e){++$fail;echo "GROUP FAIL $name ".get_class($e).' '.$e->getMessage()."\n";}}
function queryids(PDO $p,string $sql,array $args):array{$q=$p->prepare($sql);$q->execute($args);return array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}
function png(int $i):string{$chunk=static fn(string $type,string $b):string=>pack('N',strlen($b)).$type.$b.pack('N',crc32($type.$b));$row="\0".str_repeat(chr(17*$i).chr(255-13*$i).chr(9*$i),16);return "\x89PNG\r\n\x1a\n".$chunk('IHDR',pack('NNCCCCC',16,16,8,2,0,0,0)).$chunk('IDAT',gzcompress(str_repeat($row,16))).$chunk('IEND','');}
if(($argv[2]??'')==='media'){
 group('MKT-L376 bounded signed media ACK',function()use($c,$p,$admin,$W){$g=$c->guestContent();$m=$c->marketing();$sources=[];for($i=1;$i<=10;$i++){$file=$W.'/cc08-png-'.$i.'.png';file_put_contents($file,png($i));$a=$g->importUpload($file,'qa-cc08-'.$i.'.png','qa cover '.$i,$admin);$key=$a['media_key'];$m->saveCampaign(['name'=>'qa-cc08-'.$i,'headline'=>'qa-cc08-cover-'.$i,'status'=>'active','public_visible'=>true,'cover_media_key'=>$key],$admin);$sources[]='media:'.$key;}
