 $status=$client->post('/api/v1/local/guest/media/status',['media_manifest'=>$manifest],10)['body'];$initial=(int)$status['missing_count'];ck($initial>=10,'initial signed probe missing at least ten replicas');$previous=$initial;$complete=false;
 for($i=1;$i<=32;$i++){$r=$publisher->syncGuestPublication(10);$s=$r['state'];$remote=$client->post('/api/v1/local/guest/media/status',['media_manifest'=>$manifest],10)['body'];$missing=(int)$remote['missing_count'];$media=$r['channels']['guest_media']??[];echo 'ROUND '.json_encode(['round'=>$i,'uploaded'=>$media['uploaded']??null,'missing'=>$missing,'local_ready'=>$s['media_ready']??null,'critical_ready'=>$s['critical_ready']??null,'status'=>$s['status']??null,'code'=>$media['code']??null,'failed_channel'=>$s['failed_channel']??null],JSON_UNESCAPED_UNICODE)."\n";
 ck(($s['critical_ready']??false)===true&&($s['expected_revision_id']??null)===$before['revision_id']&&($s['ack_revision_id']??null)===$before['revision_id'],'exact critical ACK while media progresses');ck(($media['ok']??false)===true&&(int)($media['uploaded']??999)<=8,'bounded upload iteration');ck($missing<=$previous,'missing replicas never increase');if($missing===0){ck(($remote['complete']??false)===true&&($s['media_ready']??false)===true&&($s['status']??'')==='synced','full signed media ACK verified independently');$complete=true;break;}ck(($s['media_ready']??true)===false&&($s['status']??'')==='partial','honest degraded status');ck($missing<$previous,'media progress in bounded iteration');$previous=$missing;}
 ck($complete,'all required media replicated');$re=$publisher->syncGuestPublication(10);ck(($re['state']['media_ready']??false)===true&&(int)($re['channels']['guest_media']['uploaded']??-1)===0,'deduplicated final media round');});exit($fail?1:0);
