group('STAFF-L086 historical personnel and access',function()use($c,$p,$aid,$pid,$admin,$proxy,&$out){$q=$p->prepare('INSERT INTO personnel(display_name,personnel_code,active) VALUES(?,?,1)');$q->execute(['QA former CC08','QA-CC08-former']);$former=(int)$p->lastInsertId();$q->execute(['QA active CC08','QA-CC08-active']);$active=(int)$p->lastInsertId();$day=$c->businessClock()->assignment()['business_date'];$oid=(int)$p->query("SELECT id FROM orders WHERE public_code='qa150-order-0'")->fetchColumn();ck($oid>0,'synthetic order for historical record');$q=$p->prepare("INSERT INTO staff_consumptions(public_code,client_token,order_id,consumer_personnel_id,recorded_by_user_id,menu_value_amount,benefit_amount,discount_amount,payable_amount,known_cost_amount,consumer_name_snapshot,calculation_snapshot_json,business_date,business_shift_key) VALUES('QA-CC08-former-doc','qa-cc08-former-doc',?,?,?,25000,0,0,25000,0,'QA former CC08','{}',?,'qa')");$q->execute([$oid,$former,$aid,$day]);$doc=(int)$p->lastInsertId();$p->beginTransaction();try{$c->staffAccountService()->chargeConsumptionTx($doc,$aid,$day.' 12:00:00');$p->commit();}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}$p->prepare('UPDATE personnel SET active=0,archived_at=UTC_TIMESTAMP() WHERE id=?')->execute([$former]);$s=$c->staffConsumptionWorkspace()->snapshot($admin);$current=array_column($s['personnel'],null,'id');$historical=array_column($s['historical_personnel'],null,'id');ck(isset($current[$active])&&!isset($current[$former]),'new consumption list active only');ck(isset($historical[$active],$historical[$former])&&(int)$historical[$former]['historical_only']===1,'account report historical selector includes former');$acc=$c->staffAccountService()->account($former,$admin);ck($acc['balance']===25000&&count($acc['history'])===1,'former account real ledger retained');$rep=$c->staffConsumptionReports()->report(['from'=>$day,'to'=>$day,'personnel_id'=>$former],$admin);ck((int)$rep['summary']['document_count']===1&&(int)$rep['summary']['payable_amount']===25000,'former report real document retained');$history=$c->staffConsumptionWorkspace()->history($former,$admin);ck(count($history['rows'])===1,'former consumption history retained');$blocked=false;try{$c->staffConsumptionFoundation()->proxyConsumer($former,$admin);}catch(Throwable $e){$blocked=($e->errorCode??'')==='personnel_unavailable';}ck($blocked,'former cannot be new consumer');$p->prepare("INSERT INTO user_capabilities(user_id,capability,enabled) VALUES(?,'staff_consumption_proxy',1) ON DUPLICATE KEY UPDATE enabled=1")->execute([$pid]);$s=$c->staffConsumptionWorkspace()->snapshot($proxy);ck($s['historical_personnel']===[]&&!in_array($former,array_map('intval',array_column($s['personnel'],'id')),true),'proxy only cannot see archived personnel');$blocked=false;try{$c->staffAccountService()->account($former,$proxy);}catch(Throwable $e){$blocked=($e->httpStatus??0)===403;}ck($blocked,'proxy cannot read former ledger');$out['former']=$former;$out['active']=$active;$out['day']=$day;});
group('CAT-L309 category membership commit and rollback',function()use($c,$p,$admin,&$out){$q=$p->prepare("INSERT INTO menus(menu_key,name,status) VALUES(?,?,'active')");$q->execute(['qa-cc08-menu-a','QA menu A']);$a=(int)$p->lastInsertId();$q->execute(['qa-cc08-menu-b','QA menu B']);$b=(int)$p->lastInsertId();$svc=$c->catalogAdmin();$data=['name'=>'QA CC08 category','menu_ids'=>[$a,$b],'lifecycle_status'=>'active','guest_visible'=>true,'staff_visible'=>true];$cat=(int)$svc->saveCategory($data,$admin)['id'];$data['id']=$cat;$q=$p->prepare('INSERT INTO items(item_code,category_id,name,price) VALUES(?,?,?,10000)');$q->execute(['qa-cc08-item-a',$cat,'QA CC08 item A']);$i=(int)$p->lastInsertId();$q->execute(['qa-cc08-item-b',$cat,'QA CC08 item B']);$j=(int)$p->lastInsertId();$ins=$p->prepare('INSERT INTO menu_items(menu_id,item_id) VALUES(?,?)');foreach([$i,$j] as $id){$ins->execute([$a,$id]);$ins->execute([$b,$id]);}$p->prepare("UPDATE items SET active=0,lifecycle_status='retired' WHERE id=?")->execute([$j]);$data['menu_ids']=[$a];$svc->saveCategory($data,$admin);ck(queryids($p,'SELECT menu_id FROM menu_categories WHERE category_id=? ORDER BY menu_id',[$cat])===[$a],'category membership committed');foreach([$i,$j] as $id)ck(queryids($p,'SELECT menu_id FROM menu_items WHERE item_id=? ORDER BY menu_id',[$id])===[$a],'current and retired item intersection preserved');$p->exec("CREATE TRIGGER qa_cc08_menu_fail BEFORE INSERT ON menu_items FOR EACH ROW BEGIN IF NEW.item_id={$i} THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='qa injected membership failure'; END IF; END");$failed=false;try{$data['name']='QA rejected name';$data['menu_ids']=[$a,$b];$svc->saveCategory($data,$admin);}catch(Throwable $e){$failed=str_contains($e->getMessage(),'qa injected membership failure');}finally{$p->exec('DROP TRIGGER IF EXISTS qa_cc08_menu_fail');}ck($failed&&!$p->inTransaction(),'injected mid-transaction failure rolled back');ck(queryids($p,'SELECT menu_id FROM menu_categories WHERE category_id=? ORDER BY menu_id',[$cat])===[$a]&&queryids($p,'SELECT menu_id FROM menu_items WHERE item_id=? ORDER BY menu_id',[$i])===[$a]&&queryids($p,'SELECT menu_id FROM menu_items WHERE item_id=? ORDER BY menu_id',[$j])===[$a],'all memberships unchanged after failure');$q=$p->prepare('SELECT name FROM categories WHERE id=?');$q->execute([$cat]);ck($q->fetchColumn()==='QA CC08 category','category metadata rollback');$out['cat']=$cat;});
group('REP-L278 actual range workbook data',function()use($c,$p,$aid,$pid,$W,&$out){$day=$c->time()->civilDate();$ins=$p->prepare("INSERT INTO audit_log(actor_user_id,action,entity_type,entity_id,details_json,source_ip,user_agent,created_at) VALUES(?,?,?,?,?,?,'qa-private-agent',?)");$ids=[];for($i=0;$i<105;$i++){$ins->execute([$aid,'qa_case08.export','qa_test','literal%_'.$i,'{"test":"qa-secret-marker"}','192.0.2.1',$day.' 12:00:00']);$ids[]=(int)$p->lastInsertId();}$ins->execute([$pid,'qa_case08.export','qa_test','literal%_other','{}','192.0.2.2',$day.' 12:00:00']);$ins->execute([$aid,'qa_case08.export','qa_test','literalXXother','{}','192.0.2.2',$day.' 12:00:00']);$r=$c->reporting()->report($day,$day);$a=$c->reporting()->activityReport($day,$day,$aid,'qa_case08','literal%_',100,0);ck((int)$a['summary']['events']===105&&count($a['rows'])===100,'actual filtered activity spans two pages');$bytes=$c->reporting()->currentViewWorkbook($day,$day,true,$aid,'qa_case08','literal%_');ck(str_starts_with($bytes,"PK\x03\x04"),'real XLSX service output');file_put_contents($W.'/cc08-admin.xlsx',$bytes);$bytes=$c->reporting()->currentViewWorkbook($day,$day,false,$aid,'qa_case08','literal%_');file_put_contents($W.'/cc08-nonaudit.xlsx',$bytes);$out['export']=['day'=>$day,'actor'=>$aid,'net_sales'=>(int)$r['summary']['net_sales'],'ids'=>array_reverse($ids)];});
